import { useThemeContext } from "./ThemeProvider";
import ThemeToggler from "./ThemeTogglerEx";

export default function AppContainer({children}){
    const {isDarkThemeActive} = useThemeContext();
    return<><div className={`app-container ${isDarkThemeActive ? 'dark-mode' : 'light-mode'}`}>
    <ThemeToggler/>
    {children}
    </div></>
}
